// Server side of the CRM reminders, run from the existing /api/wfh-remind
// cron (no extra serverless function, no extra cron slot).
//
//   1. Calls crm_run_reminders() so reminders are generated even on a
//      database without pg_cron.
//   2. Pushes the reminder notifications nobody's browser has pushed yet
//      (Web Push reaches people with WorkSuite closed), then marks them.
//
// Only the kinds generated by crm_run_reminders() are pushed here. Every
// other notification is pushed by the browser of the person who caused it,
// so pushing those again would notify people twice.

const PUSH_KINDS = ['task.reminder', 'task.digest', 'event.reminder', 'lead.follow_up', 'invoice.overdue'];
const WINDOW_HOURS = 24;       // older unpushed reminders are stale; leave them in the bell only
const BATCH = 500;

/**
 * runAndPush({ url, key, webpush, vapid: { publicKey, privateKey, subject }, request = fetch, now = Date.now() })
 * -> { generated, queued, pushed, noSubscription, cleaned } | { skipped } | { error }
 * Never throws: reminders are a side job of a cron that has other work to do.
 */
async function runAndPush({ url, key, webpush, vapid = {}, request = fetch, now = Date.now() }) {
  const H = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };
  const out = { generated: null, queued: 0, pushed: 0, noSubscription: 0, cleaned: 0 };
  try {
    const rr = await request(`${url}/rest/v1/rpc/crm_run_reminders`, { method: 'POST', headers: H, body: '{}' });
    if (rr.status === 404) return { skipped: 'crm_reminders_not_installed' };
    if (rr.ok) out.generated = await rr.json().catch(() => null);
    else out.generate_error = `HTTP ${rr.status}`;

    if (!vapid.publicKey || !vapid.privateKey || !webpush) return { ...out, skipped_push: 'no_vapid' };

    const since = new Date(now - WINDOW_HOURS * 3600 * 1000).toISOString();
    const q = await request(`${url}/rest/v1/notifications?select=id,user_id,kind,title,body,url`
      + `&pushed_at=is.null&kind=in.(${PUSH_KINDS.join(',')})&created_at=gte.${encodeURIComponent(since)}`
      + `&order=created_at.asc&limit=${BATCH}`, { headers: H });
    if (!q.ok) return { ...out, error: 'notification queue unavailable' };
    const items = await q.json();
    out.queued = items.length;
    if (!items.length) return out;

    const users = [...new Set(items.map(i => i.user_id))];
    const s = await request(`${url}/rest/v1/push_subscriptions?select=user_id,endpoint,p256dh,auth&user_id=in.(${users.join(',')})`, { headers: H });
    const subs = s.ok ? await s.json() : [];
    const byUser = new Map();
    subs.forEach(x => { if (!byUser.has(x.user_id)) byUser.set(x.user_id, []); byUser.get(x.user_id).push(x); });

    webpush.setVapidDetails(vapid.subject || 'mailto:network.admin@sportsmart.com', vapid.publicKey, vapid.privateKey);
    const gone = new Set();
    for (const n of items) {
      const mine = (byUser.get(n.user_id) || []).filter(x => !gone.has(x.endpoint));
      if (!mine.length) { out.noSubscription++; continue; }
      const payload = JSON.stringify({ title: n.title, body: n.body || '', url: n.url || '/', tag: n.kind });
      let delivered = false;
      await Promise.all(mine.map(async x => {
        try {
          await webpush.sendNotification({ endpoint: x.endpoint, keys: { p256dh: x.p256dh, auth: x.auth } }, payload, { TTL: 3600, urgency: 'normal' });
          delivered = true;
        } catch (e) {
          if (e && (e.statusCode === 404 || e.statusCode === 410)) gone.add(x.endpoint);
        }
      }));
      if (delivered) out.pushed++;
    }

    // Expired browser subscriptions are removed, as /api/push does.
    for (const endpoint of gone) {
      try { await request(`${url}/rest/v1/push_subscriptions?endpoint=eq.${encodeURIComponent(endpoint)}`, { method: 'DELETE', headers: H }); out.cleaned++; }
      catch { /* try again next run */ }
    }

    // Marked even when a person has no device: the bell still shows it, and it must not be retried forever.
    const ids = items.map(i => i.id);
    const m = await request(`${url}/rest/v1/notifications?id=in.(${ids.join(',')})`, {
      method: 'PATCH', headers: { ...H, Prefer: 'return=minimal' }, body: JSON.stringify({ pushed_at: new Date(now).toISOString() }),
    });
    if (!m.ok) out.mark_error = `HTTP ${m.status}`;
    return out;
  } catch (e) {
    return { ...out, error: String((e && e.message) || e).slice(0, 200) };
  }
}

module.exports = { runAndPush, PUSH_KINDS };
